<?php
declare(strict_types=1); namespace App\Http\Controllers\Classrooms;
use App\Http\Controllers\Controller; use App\Http\Requests\Classrooms\{StoreClassroomRequest,UpdateClassroomRequest}; use App\Models\{AcademicYear,Classroom,GradeLevel,Personnel,SchoolProfile,Semester,Student}; use App\Services\Classrooms\ClassroomService; use Illuminate\Http\Request; use Illuminate\Http\RedirectResponse; use Illuminate\View\View;
class ClassroomController extends Controller {public function index(Request $r,ClassroomService $s):View{$this->authorize('viewAny',Classroom::class);$years=AcademicYear::latest('starts_at')->get();$year=(int)($r->integer('academic_year')?:AcademicYear::where('is_active',true)->value('id'));$q=Classroom::with(['gradeLevel','academicYear','homeroomPersonnel'])->withCount('activeMemberships')->where('academic_year_id',$year);if(!$r->user()->can('classrooms.view'))$q->where('homeroom_personnel_id',$r->user()->personnel?->id??0);$rooms=$q->orderBy('grade_level_id')->orderBy('code')->get();return view('classrooms.index',['years'=>$years,'selectedYear'=>$year,'classrooms'=>$rooms,'stats'=>$s->statistics($year?:null),'checks'=>['Profil madrasah sudah tersedia'=>SchoolProfile::exists(),'Tahun ajaran aktif sudah tersedia'=>AcademicYear::where('is_active',true)->exists(),'Semester aktif sudah tersedia'=>Semester::where('is_active',true)->exists(),'Data personalia tersedia'=>Personnel::exists(),'Data siswa tersedia'=>Student::exists()]]);}public function create():View{$this->authorize('create',Classroom::class);return view('classrooms.form',$this->options());}public function store(StoreClassroomRequest $r,ClassroomService $s):RedirectResponse{$c=$s->create($r->user(),$r->validated());return redirect()->route('classrooms.show',$c)->with('success','Rombongan belajar berhasil ditambahkan.');}public function show(Classroom $classroom):View{$this->authorize('view',$classroom);$classroom->load(['academicYear','gradeLevel','homeroomPersonnel','activeMemberships.student','createdBy','updatedBy']);return view('classrooms.show',compact('classroom'));}public function edit(Classroom $classroom):View{$this->authorize('update',$classroom);return view('classrooms.form',[...$this->options(),'classroom'=>$classroom]);}public function update(UpdateClassroomRequest $r,Classroom $classroom,ClassroomService $s):RedirectResponse{$s->update($r->user(),$classroom,$r->validated());return redirect()->route('classrooms.show',$classroom)->with('success','Rombongan belajar berhasil diperbarui.');}private function options():array{return ['years'=>AcademicYear::latest('starts_at')->get(),'grades'=>GradeLevel::where('is_active',true)->orderBy('sort_order')->get(),'personnel'=>Personnel::where('is_active',true)->where(fn($q)=>$q->where('position','like','%Guru%')->orWhere('position','like','%Kepala Madrasah%'))->orderBy('full_name')->get()];}}
